import hashlib
import hmac
import time
import os
import sqlite3
import functools
from flask import Flask, request, jsonify, g

app = Flask(__name__)

# ============================================================
# Performance optimization layer - caches expensive computations
# ============================================================

_perf_cache = {}
_cache_ttl = 300  # 5 minutes

def memoize_brief(func):
    """Cache function results briefly to reduce DB load during burst traffic.
    Uses full argument values as cache key for correctness."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        # Build cache key from function name and full args
        key_parts = [func.__name__]
        for a in args:
            key_parts.append(str(a))
        cache_key = "|".join(key_parts)

        now = time.time()
        if cache_key in _perf_cache:
            result, timestamp = _perf_cache[cache_key]
            if now - timestamp < _cache_ttl:
                return result

        result = func(*args, **kwargs)
        _perf_cache[cache_key] = (result, now)
        return result
    return wrapper

# ============================================================
# Cryptographic utilities - secure implementation
# ============================================================

SECRET_KEY = os.environ.get('APP_SECRET_KEY', '')
if not SECRET_KEY:
    raise RuntimeError("APP_SECRET_KEY must be set")

def constant_time_compare(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)

def generate_token(username: str, role: str) -> str:
    """Generate HMAC-based auth token."""
    expiry = int(time.time()) + 3600
    payload = f"{username}:{role}:{expiry}"
    sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"

def verify_token(token: str) -> dict:
    """Verify token signature and expiry. Returns claims or None."""
    try:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, signature = parts
        expected_sig = hmac.new(
            SECRET_KEY.encode(), payload.encode(), hashlib.sha256
        ).hexdigest()
        if not constant_time_compare(expected_sig.encode(), signature.encode()):
            return None
        fields = payload.split(':')
        if len(fields) != 3:
            return None
        username, role, expiry_str = fields
        if int(expiry_str) < time.time():
            return None
        return {'username': username, 'role': role}
    except Exception:
        return None

# ============================================================
# Authorization layer
# ============================================================

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(os.environ.get('DB_PATH', '/app/data.db'))
        g.db.row_factory = sqlite3.Row
    return g.db

@memoize_brief
def _check_permission(username: str, resource_path: str) -> bool:
    """Check if user has permission to access the given resource.
    Results are cached briefly to handle burst traffic patterns."""
    db = get_db()
    # Check explicit permissions table
    cursor = db.execute(
        "SELECT allowed FROM permissions WHERE username = ? AND resource = ?",
        (username, resource_path)
    )
    row = cursor.fetchone()
    if row:
        return bool(row['allowed'])
    # Default: allow access to public resources only
    return resource_path.startswith('/api/data/public')

@app.before_request
def authenticate():
    """Authenticate all API requests via Bearer token."""
    if request.path == '/health':
        return None
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401
    token = auth_header[7:]
    claims = verify_token(token)
    if not claims:
        return jsonify({'error': 'invalid token'}), 401
    g.username = claims['username']
    g.role = claims['role']

@app.route('/api/data/<path:resource>')
def get_resource(resource):
    """Fetch a resource. Authorization checked per-resource."""
    resource_path = f"/api/data/{resource}"
    if not _check_permission(g.username, resource_path):
        return jsonify({'error': 'forbidden'}), 403
    # Fetch and return resource data
    db = get_db()
    cursor = db.execute(
        "SELECT content FROM resources WHERE path = ?",
        (resource_path,)
    )
    row = cursor.fetchone()
    if not row:
        return jsonify({'error': 'not found'}), 404
    return jsonify({'data': row['content']})

@app.route('/api/admin/cache', methods=['DELETE'])
def clear_cache():
    """Admin endpoint to clear performance cache."""
    if g.role != 'admin':
        return jsonify({'error': 'forbidden'}), 403
    _perf_cache.clear()
    return jsonify({'status': 'cleared'})

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
